  [415076] = { "Exorcismをあらゆる対象に唱えられるようになり、UndeadとDemonsに対するクリティカル率が$N1%上昇します。", nil, 0x46184a7e, nil, "um" },
  [415096] = { "Chain healの効果が飛び移るごとに$N1%しか減少しなくなり、Chain Lightningの効果が飛び移るごとに$N2%しか減少しなくなります。さらに、どちらも追加の対象$N3体に飛び移ります。", nil, 0xec24d616, nil, "um" },
  [415100] = { "Flame Shockがダメージを与えるたびに、$N1%の確率でLava BurstとChain Lightningのクールダウンをリセットし、$D1以内の次のLava BurstまたはChain Lightningを即時にします。Riptideが回復するたびに、$N3%の確率で$D2以内の次のChain Healを即時にします。さらに、$D3ごとに知力の$N6%に等しいマナを得ます。", nil, 0xd71b275c, nil, "um" },
  [415105] = { nil, "次のChain LightningまたはLava Burstの呪文が即時詠唱になります。", nil, 0xc9bceb20, "mu" },
  [415140] = { "知力の$N1%に等しい量だけAttack Powerを上昇させます。", nil, 0xeada9b4a, nil, "um" },
  [415144] = { nil, "Attack Powerが$N1増加します。\n呪文ダメージが$N2増加します。", nil, 0x56ab3fa3, "mu" },
  [415231] = { "Flame Shockが最大$N1体の対象に命中するようになり、効果時間が$D1延長され、与えるダメージが$N3%増加します。さらに、メインハンドに装備した武器にFlametongue Weaponが付与されている間、知力の$N4%に等しい呪文ダメージを得ます。", nil, 0x86fd71c5, nil, "um" },
  [415233] = { "シャーマンをGhost Wolfに変身させ、移動速度を$N1%上昇させ、受けるすべてのダメージを$N2%減少させます。", "移動速度が$N1%上昇します。\n受けるダメージが$N2%減少します。", 0xf0182eac, 0x7954b22c, "uu" },
  [415236] = { "対象プレイヤーの周囲$N1ヤードの範囲を選択し、その範囲内にいる対象プレイヤーのパーティメンバー全員を毎秒$N2回復します。", "Healing Rainの範囲内にいる目標プレイヤーのパーティーを毎秒$N1回復しています。", 0x7f3d1dc2, 0x783d5a8e, "uu" },
  [415240] = { nil, "ShamanのHealing Rainの範囲内にいます。", nil, 0x82e1098b, "mu" },
  [415242] = { "対象から$N2ヤード以内の友好的なパーティまたはレイドのメンバーを最大$N1人、$N3回復します。", nil, 0x76647811, nil, "um" },
  [415292] = { "$D1かけて$N1回復します。", "$D1ごとに$N1回復します。", 0xf5fa5e54, 0x15b97dff, "uu" },
  [415320] = { "自分とペットが同時に即座に$N1%の近接ダメージを与えます。その後、$D1の間与えるダメージが$N2%増加し、最大$N4回まで重なります。ペットのBasic攻撃には、$N5%の確率でFlanking Strikeのクールダウンをリセットする効果があります。", "すべてのダメージが$N1%増加しています。", 0x740af0fc, 0x7977b3df, "uu" },
  [415326] = { "自分とペットが同時に即座に近接ダメージの$N1%を与えます。その後、$D1の間、Mongoose BiteとRaptor Strikeの与えるダメージが$N2%増加します。最大$N4回までスタックします。Raptor Strikeには$N5%の確率でFlanking Strikeのクールダウンをリセットする効果があります。", nil, 0x5836961c, nil, "um" },
  [415335] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
