  [415343] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [415352] = { "Raptor Strikeが即時になり、Mongoose BiteとRaptor Strikeは攻撃のたびに$N1%の確率でMongoose BiteとRaptor Strikeのクールダウンをリセットします。", nil, 0x01109410, nil, "um" },
  [415358] = { "Raptor Strikeは、$D1の間、Raptor StrikeとMongoose Biteの与えるダメージを$N1%増加させます。最大$N3回までスタックします。重ねがけしてもこの効果の効果時間は延長されません。", nil, 0xc6ec38f2, nil, "um" },
  [415362] = { nil, "Raptor StrikeとMongoose Biteのダメージが$N1%増加します。", nil, 0x5c4cbf9d, "mu" },
  [415370] = { "ペットを連れていない間、すべての攻撃で与えるダメージが$N1%増加します。", nil, 0x00437013, nil, "um" },
  [415372] = { nil, "ペットがいる間、ダメージが$N1%減少します。", nil, 0x08033dd9, "mu" },
  [415399] = { "直前の1秒間移動していないと、$N2%の確率でSniper's Aimを得ます。最大$N3回までスタックします。Sniper's Aimは、Shotのアビリティのクリティカル率を$N4%上昇させます。", nil, 0x666248c2, nil, "um" },
  [415401] = { nil, "Shotアビリティのクリティカル率が$N1%上昇します。", nil, 0x33595f54, "mu" },
  [415405] = { "Rapid Fireの再使用時間を$N1分短縮します。さらに、雑魚ではない敵を倒すか、敵がSerpent Stingを受けたまま死ぬと、Rapid Killingを得て、$D2以内に次に使うShot系アビリティのダメージが$N3%増加します。", nil, 0x780100d7, nil, "um" },
  [415407] = { "次のShotのアビリティのダメージが$N1%増加します。", "次のShotアビリティで与えるダメージが$N1%増加します。", 0x234e79c9, 0x4114209a, "uu" },
  [415413] = { "罠を設置するたびに、$D1以内の次のShotのアビリティ（Scatter Shotを除く）はマナを消費せず、クールダウンも発生しません。", nil, 0x623278dd, nil, "um" },
  [415414] = { nil, "次のShotアビリティはマナを消費せず、クールダウンも発生しません。", nil, 0x7cac3007, "mu" },
  [415423] = { "ハンターがマムシの相を帯び、遠隔および近接の自動攻撃でマナを回復するようになりますが、与えるダメージの合計が$N1%減少します。さらに、$N3秒ごとに最大マナの$N2%を得ます。得られるマナは武器の速度に基づきます。一度に有効にできるAspectは一つだけです。", "遠隔と近接の自動攻撃で基本マナの一定割合を回復しますが、与えるダメージの合計が$N1%減少します。さらに、$N3秒ごとに最大マナの$N2%を獲得します。", 0x5c074219, 0xcddcfcf7, "uu" },
  [415428] = { "自分の回避率が$N1%、ペットの回避率が$N2%上昇します。さらに、Flanking Strikeのアビリティのクールダウンが$N3%短縮されます。", nil, 0x62e616f4, nil, "um" },
  [415449] = { "Runeが刻まれたWaistスロットのアイテムを装備すると、このスロットのアビリティが有効になります。", nil, 0xa309a047, nil, "um" },
  [415450] = { "Runeが刻まれたFeetスロットのアイテムを装備すると、このスロットのアビリティが有効になります。", nil, 0x94e65c6e, nil, "um" },
  [415452] = { "Improved Swipeのアビリティを得ます：\n\n$I1\nCat Formの間はSwipeのアビリティがSwipe (Cat)になり、Bear Formの間はSwipeのアビリティが追加の敵最大$N1体に命中するようになります。\n\nSwipe (Cat)\n$I2\n近くの敵を薙ぎ払い、武器ダメージの$N2%を与え、現在の対象にコンボポイントを$N3獲得します。", nil, 0xe2527d73, nil, "um" },
  [415457] = { "Fan of Knivesのアビリティを得ます：\n\n$I1\n$N1ヤード以内のすべての対象に即座に両方の武器を投げつけ、短剣では武器ダメージの$N2%、その他すべての武器では武器ダメージの$N3%を与えます。", nil, 0x86e39fc3, nil, "um" },
  [415459] = { "Spell Powerのアビリティを得ます：\n\n$I1\nすべての呪文のクリティカルダメージボーナスが$N1%増加します。", nil, 0xa9c610a1, nil, "um" },
  [415460] = { "Burnoutのアビリティを得ます：\n\n$I1\nすべての呪文の呪文クリティカル率が$N1%上昇しますが、非周期の呪文がクリティカルになると、基本マナの$N2%が追加のマナコストとして消費されるようになります。", nil, 0x912f7738, nil, "um" },
  [415467] = { "Mass Regenerationのアビリティを得ます：\n\n$I1\n対象のプレイヤーから$N1ヤード以内にいる、そのプレイヤーのパーティーメンバー全員の体力を$D1かけて$N2回復し、それぞれに$D2の間Temporal Beaconを付与します。\n\nTemporal Beacon\n$I2\n対象の時空上の位置を記録します。術者が与えるすべてのArcaneダメージの$N5%が、術者の現在のTemporal Beaconの対象それぞれへの時間術の治癒に変換されます。この治癒は自分自身に対しては$N6%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N7%減少します。", nil, 0x86eeedaf, nil, "um" },
  [415481] = { "Pain and Sufferingのアビリティを得ます：\n\n$I1\nMind Blast、Mind Spike、Mind Flayが、対象にかかっているShadow Word: Pain、Void Plague、Vampiric Touchのうち一つの効果時間を最大まで戻します。必ず残り時間が最も短いものが更新されます。", nil, 0x7cb5a1d2, nil, "um" },
  [415598] = { "Gladiator Stanceのアビリティを得ます：\n\n$I1\n攻撃的なスタンスです。盾を装備している間、与えるダメージが$N1%増加し、ブロック率が$N2%上昇しますが、アーマーが$N3%、発生する脅威が$N4%減少します。さらに、自分を狙っていない敵に自動攻撃でダメージを与えると、得る怒りが$N5%増加します。\n\nGladiator Stanceで盾を装備している間は、他のスタンス専用のアビリティをすべて使用できます。", nil, 0x319f5c03, nil, "um" },
  [415599] = { "Single-Minded Furyのアビリティを得ます：\n\n$I1\n二刀流の間、移動速度が$N1%上昇し、近接の自動攻撃が直前の自動攻撃と同じ対象に命中するたびに攻撃速度が$N2%上昇します。最大$N3回までスタックします。$D1、または自動攻撃が別の対象に命中するまで持続します。", nil, 0xc40147a1, nil, "um" },
  [415604] = { "Everlasting Afflictionのアビリティを得ます：\n\n$I1\nDrain Life、Drain Soul、Shadowboltの呪文がダメージを与えるたびに、対象にかかっている自分のCorruptionの効果時間が最大まで更新されます。", nil, 0x00f13609, nil, "um" },
  [415605] = { "Demonic Tacticsのアビリティを得ます：\n\n$I1\n召喚したDemonが有効な間、自分と召喚したDemonのすべての攻撃のクリティカル率が$N1%上昇します。", nil, 0xe829f2ef, nil, "um" },
  [415703] = { "Sacred Shieldのアビリティを得ます：\n\n$I1\n対象はダメージを受けるたびにSacred Shieldを得て、最大$D1の間、$N1のダメージを吸収し、パラディンのFlash of Lightのクリティカル率を$N2%上昇させます。さらに、Flash of LightがSacred Shieldのかかった対象を$D2かけて追加で$N4%回復するようになります。この効果は$D3に一度までしか得られません。$D4持続します。この呪文は同時に一つの対象にしかかけられません。", nil, 0xf4acd0fe, nil, "um" },
  [415706] = { "The Art of Warのアビリティを得ます：\n\n$I1\n与えるすべてのHolyダメージが$N1%増加し、近接攻撃と呪文のクリティカルによりExorcismの呪文の残りクールダウンが$D1短縮されます。", nil, 0xd05623ee, nil, "um" },
  [415709] = { "Survival of the Fittestのアビリティを得ます：\n\n$I1\n近接攻撃でクリティカルヒットを受ける確率が$N1%減少し、受けるすべてのダメージが$N2%減少します。Bear FormまたはDire Bear Formの間は、受けるダメージがさらに$N3%減少します。", nil, 0x55e5ed41, nil, "um" },
  [415712] = { "Power Surgeのアビリティを得ます：\n\n$I1\nFlame Shockがダメージを与えるたびに、$N1%の確率でLava BurstとChain Lightningのクールダウンをリセットし、$D1以内の次のLava BurstまたはChain Lightningを即時にします。Riptideが回復するたびに、$N3%の確率で$D2以内の次のChain Healを即時にします。さらに、$D3ごとに知力の$N6%に等しいマナを得ます。", nil, 0xc25cf07c, nil, "um" },
  [415713] = { "Mental Dexterityのアビリティを得ます：\n\n$I1\n知力の$N1%に等しい分だけAttack Powerが上昇します。", nil, 0x95cf3c2c, nil, "um" },
  [415714] = { "Healing Rainのアビリティを得ます：\n\n$I1\n対象のプレイヤーの周囲$N1ヤードの範囲を選び、その範囲内にいる対象のプレイヤーのパーティーメンバー全員の体力を毎秒$N2回復します。", nil, 0x10219417, nil, "um" },
  [415717] = { "Catlike Reflexesのアビリティを得ます：\n\n$I1\n自分の回避率が$N1%、ペットの回避率が$N2%上昇します。さらに、Flanking Strikeのアビリティのクールダウンが$N3%短縮されます。", nil, 0x80e98739, nil, "um" },
  [415718] = { "Aspect of the Viperのアビリティを得ます：\n\n$I1\nハンターがヴァイパーの相を身にまとい、遠隔と近接の自動攻撃でマナを回復するようになりますが、与える総ダメージが$N1%減少します。さらに、$D1ごとに最大マナの$N2%を得ます。得られるマナは武器の速度に基づきます。同時に有効にできるAspectは一つだけです。", nil, 0x5189d140, nil, "um" },
  [415719] = { "Lock and Loadのアビリティを得ます：\n\n$I1\n罠を設置するたびに、$D1以内の次のShotのアビリティ（Scatter Shotを除く）はマナを消費せず、クールダウンも発生しません。", nil, 0xea616c73, nil, "um" },
  [415720] = { "Kill Shotのアビリティを得ます：\n\n$I1\n手負いの対象にとどめを刺そうと遠隔攻撃を放ち、武器ダメージの$N1%に加えて$N2のダメージを与えます。Kill Shotには最小射程がありません。体力が20%以下の敵に使用すると、Kill Shotのクールダウンがリセットされます。", nil, 0xf8c116e8, nil, "um" },
  [415723] = { "Melee Specialistのアビリティを得ます：\n\n$I1\nRaptor Strikeが即時になり、Mongoose BiteとRaptor Strikeは攻撃のたびに$N1%の確率でMongoose BiteとRaptor Strikeのクールダウンをリセットします。", nil, 0xfbec55e5, nil, "um" },
  [415725] = { "Waylayのアビリティを得ます：\n\n$I1\nAmbushとBackstabの命中が対象の体勢を崩し、$D1の間、近接攻撃の間隔を$N1%延ばし、移動速度を$N2%低下させます。", nil, 0x877c5ec1, nil, "um" },
  [415729] = { "Enlightenmentのアビリティを得ます：\n\n$I1\nマナが$N2%を超えている間、与えるダメージが$N1%増加します。マナが$N3%未満の間は、詠唱中もマナ回復の$N4%が継続します。", nil, 0xebf46f81, nil, "um" },
  [415734] = { "Spellfrost Boltのアビリティを得ます：\n\n$I1\n敵に呪氷の矢を放ち、$N1のSpellfrostダメージを与え、$D1の間、移動速度を$N2%低下させます。この呪文は対象のFrostとArcaneの耐性のうち低い方で判定され、FrostダメージとArcaneダメージの両方として扱われます。", nil, 0x0e2e915b, nil, "um" },
  [415737] = { "Serendipityのアビリティを得ます：\n\n$I1\nFlash Healで回復すると、$D1の間、次のLesser Heal、Heal、Greater Heal、Prayer of Healingの詠唱時間が$N1%短縮されます。最大$N3回までスタックします。", nil, 0x57fd02db, nil, "um" },
  [415738] = { "Mind Searのアビリティを得ます：\n\n$I1\n影の魔法の爆発を起こして敵の対象と近くの敵を攻撃し、$D2の間、$D1ごとに対象から$N4ヤード以内のすべての敵に$N1のShadowダメージを与えます。", nil, 0x5987ed1e, nil, "um" },
  [415739] = { "Lesser Heal、Heal、Greater Heal、Flash Healが、回復した対象にかかっているWeakened Soulの残り時間を$D1短縮します。さらに、Power Word: Shieldの対象はダメージが吸収されても受けたダメージから怒りを得るようになり、Power Word: Shieldが吸収したダメージでも治癒と同様にRighteous Furyが発動するようになります。", nil, 0x805cfa98, nil, "um" },
  [415740] = { "Strength of Soulのアビリティを得ます：\n\n$I1\nLesser Heal、Heal、Greater Heal、Flash Healが、回復した対象にかかっているWeakened Soulの残り時間を$D1短縮します。さらに、Power Word: Shieldの対象はダメージが吸収されても受けたダメージから怒りを得るようになり、Power Word: Shieldが吸収したダメージでも治癒と同様にRighteous Furyが発動するようになります。", nil, 0x05224e7d, nil, "um" },
  [415743] = { "Blood Surgeのアビリティを得ます：\n\n$I1\nHeroic Strike、Bloodthirst、Whirlwindは、$N1%の確率で、$D1以内の次のSlamを即時にし、両方の近接武器で攻撃させ、怒りを消費しなくします。", nil, 0x980b9a0d, nil, "um" },
  [415744] = { "Precision Timingのアビリティを得ます：\n\n$I1\nSlamが即時になりますが、$D1のクールダウンが付きます。", nil, 0xad79a82b, nil, "um" },
  [415745] = { "Focused Rageのアビリティを得ます：\n\n$I1\n攻撃的なアビリティの怒りコストを$N1減少させます。", nil, 0xae0be94f, nil, "um" },
  [415749] = { "Demonic Knowledgeのアビリティを得ます：\n\n$I1\nDemonペットを召喚している間、自分とDemonペットの呪文ダメージが、自分のレベルの最大$N1%分増加します。", nil, 0x0fcfc7c4, nil, "um" },
  [415750] = { "Incinerateのアビリティを得ます：\n\n$I1\n対象に$N1のFireダメージを与え、対象がImmolateにかかっている場合はさらに$N2%のダメージを与えます。", nil, 0xdda50ab3, nil, "um" },
  [415751] = { "Dance of the Wickedのアビリティを得ます：\n\n$I1\n敵にクリティカルを与えるたびに、自分とDemonペットが呪文クリティカル率の$N1%に等しい回避率を得て、さらに両方が最大マナの$N2%を回復します。", nil, 0x59e67555, nil, "um" },
  [415755] = { "Guarded by the Lightのアビリティを得ます：\n\n$I1\n近接攻撃をBlockingで防いだ後、$D2の間、$D1ごとに最大マナの$N1%を得ます。この効果はFlash of Light、Holy Light、Holy Shockを詠唱すると解除されます。", nil, 0xaebd2851, nil, "um" },
  [415759] = { "Skull Bashのアビリティを得ます：\n\n$I1\n13ヤード以内の対象に突進して頭蓋を殴りつけ、詠唱を妨害し、$D1の間その系統の呪文を詠唱できなくします。クールダウンはFeral Chargeと共有です。", nil, 0x565688f4, nil, "um" },
  [415760] = { "Lacerateのアビリティを得ます：\n\n$I1\n敵の対象を切り裂き、$D1かけて$N1のダメージを出血で与え、さらに対象にすでにかかっているLacerateの数ごとに武器ダメージの$N3%を与えます。大量の脅威を発生させます。この効果は同じ対象に最大$N4回までスタックします。", nil, 0x9b6d27cf, nil, "um" },
  [415761] = { "Living Seedのアビリティを得ます：\n\n$I1\n非周期の治癒呪文で対象をクリティカル回復すると、回復量の$N1%のLiving Seedを対象に植え付けます。Living Seedは、対象が次にダメージを受けるか非周期の治癒を受けたときに開花します。$D1持続します。", nil, 0x5a1b470a, nil, "um" },
  [415762] = { "Elune's Firesのアビリティを得ます：\n\n$I1\n一部の呪文とアビリティが、対象にかけた継続ダメージと継続回復の効果時間を延長します：\n\nStarfireはMoonfireを$D1延長します。\nWrathはSunfireを$D2延長します。\nRegrowthはRejuvenationを$D3延長します。\nShredはRipを$D4延長します。\n\nどの効果も、延長できるのは最初の効果時間までです。", nil, 0xfc96a093, nil, "um" },
  [415768] = { "Burnのアビリティを得ます：\n\n$I1\nFlame Shockが最大$N1体の対象に命中するようになり、効果時間が$D1延長され、与えるダメージが$N3%増加します。さらに、メインハンドに装備した武器にFlametongue Weaponが付与されている間、知力の$N4%に等しい呪文ダメージを得ます。", nil, 0x16328d70, nil, "um" },
  [415813] = { "Ghost Wolfのアビリティが屋内でも使用できるようになり、有効な間は受けるすべてのダメージが$N1%減少します。", nil, 0x25e9c32d, nil, "um" },
  [415816] = { "Wyvern Strikeのアビリティを得ます：\n\n$I1\nWyvern StingのアビリティをWyvern Strikeに置き換えます。Wyvern Strikeは武器ダメージの$N1%を与える苛烈な一撃で、対象を継続的なBleed状態にします。\n\nWyvern Strikeを使うにはWyvern Stingの才能が必要で、Survivalの呪文書にあるWyvern Stingのアビリティと置き換わります。", nil, 0x49d2169d, nil, "um" },
  [415817] = { "Rapid Killingのアビリティを得ます：\n\n$I1\nRapid Fireのアビリティのクールダウンを$D1短縮します。さらに、格下すぎない敵を倒すか、敵がSerpent Stingにかかったまま死ぬと、Rapid Killingを得て、$D2以内の次のShotのアビリティのダメージが$N3%増加します。", nil, 0xe18ce1c0, nil, "um" },
  [415818] = { "Sniper Trainingのアビリティを得ます：\n\n$I1\n直前の1秒間移動していないと、$N2%の確率でSniper's Aimを得ます。最大$N3回までスタックします。Sniper's Aimは、Shotのアビリティのクリティカル率を$N4%上昇させます。", nil, 0x8f9ebf59, nil, "um" },
  [415822] = { "Raptor Furyのアビリティを得ます：\n\n$I1\nRaptor Strikeは、$D1の間、Raptor StrikeとMongoose Biteの与えるダメージを$N1%増加させます。最大$N3回までスタックします。重ねがけしてもこの効果の効果時間は延長されません。", nil, 0xf318fadb, nil, "um" },
  [415918] = { "外套にCrimson Tempestのルーンを刻みます：\n\n$I1\n$N1ヤード以内のすべての敵を切り裂き、時間とともにBleedさせるフィニッシュ技です。コンボポイントが多いほど長く持続し、ダメージも増加します。\n\n1ポイント：4秒かけて$N3のダメージ。\n 2ポイント：6秒かけて$N6のダメージ。\n 3ポイント：8秒かけて$N9のダメージ。\n 4ポイント：10秒かけて$N12のダメージ。\n 5ポイント：12秒かけて$N15のダメージ。\n\nCrimson Tempestは、Ruptureによって発動する、またはRuptureを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0xe3ea95b8, nil, "um" },
  [415922] = { "外套にBlunderbussのルーンを刻みます：\n\n$I1\n前方の円錐範囲にいる敵最大$N1体にマスケット銃の一斉射撃を放ち、$N2のPhysicalダメージを与えます。", nil, 0xce5a37fe, nil, "um" },
  [415926] = { "ブーツにWaylayのルーンを刻みます：\n\n$I1\nAmbushとBackstabの命中で対象の体勢を崩し、$D1の間、近接攻撃の間隔を$N1%延ばし、移動速度を$N2%低下させます。", nil, 0x8f27a210, nil, "um" },
  [415934] = { "ブーツにSpell Powerのルーンを刻みます：\n\n$I1\nすべての呪文のクリティカルダメージボーナスが$N1%増加します。", nil, 0xf49948f2, nil, "um" },
  [415936] = { "手袋にLiving Bombのルーンを刻みます：\n\n$I1\n対象はLiving Bombとなり、$D1かけて$N1のFireダメージを受けます。$D2後、または呪文が解除されると、対象は爆発し、$N5ヤード以内のすべての敵に$N4のFireダメージを与えます。\n\nLiving Bombは、Scorchによって発動する、またはScorchを強化するすべてのタレントと効果の恩恵を受けます。", nil, 0x7a583662, nil, "um" },
  [415939] = { "脚部にMass Regenerationのルーンを刻みます：\n\n$I1\n対象のプレイヤーから$N1ヤード以内にいる、そのプレイヤーのパーティーメンバー全員の体力を$D1かけて$N2回復し、それぞれに$D2の間Temporal Beaconを付与します。\n\nTemporal Beacon\n$I2\n対象の時空間の位置を記録します。術者が与えたArcaneダメージの$N5%が、術者の現在のTemporal Beaconの対象それぞれへのクロノマンシーの治療に変換されます。この治療は自分に対しては$N6%減少し、複数の対象にダメージを与えるArcane呪文によるダメージの場合はさらに$N7%減少します。", nil, 0x7d1b407b, nil, "um" },
  [415942] = { "胸部か法衣にEnlightenmentのルーンを刻みます：\n\n$I1\nマナが$N2%を超えている間、与えるダメージが$N1%増加します。マナが$N3%を下回っている間、詠唱中もマナ回復の$N4%が継続します。", nil, 0xe36c7b47, nil, "um" },
  [415948] = { "ベルトにSpellfrost Boltのルーンを刻みます：\n\n$I1\n敵にスペルフロストの矢を放ち、$N1のSpellfrostダメージを与え、$D1の間、移動速度を$N2%低下させます。この呪文は対象のFrostとArcaneの耐性のうち低い方で判定され、FrostとArcane両方のダメージとして扱われます。", nil, 0x0e2ee4df, nil, "um" },
  [415991] = { "兜にPain and Sufferingのルーンを刻みます：\n\n$I1\nMind Blast、Mind Spike、Mind Flayが、対象にかかっているShadow Word: Pain、Void Plague、Vampiric Touchのいずれか一つの効果時間を最大まで更新します。更新されるのは、常に残り時間が最も短いものです。", nil, 0x1765a845, nil, "um" },
  [415995] = { "胸部か法衣にSerendipityのルーンを刻みます：\n\n$I1\nFlash Healで回復すると、$D1の間、次のLesser Heal、Heal、Greater Heal、Prayer of Healingの詠唱時間が$N1%短縮されます。最大$N3回まで累積します。", nil, 0x15382fc4, nil, "um" },
  [415996] = { "手袋にMind Searのルーンを刻みます：\n\n$I1\n影の魔法を爆発させて敵の対象と近くの敵を傷つけ、$D2の間、$D1ごとに、対象から$N4ヤード以内のすべての敵に$N1のShadowダメージを与えます。", nil, 0xc0148127, nil, "um" },
  [415997] = { "胸部か法衣にStrength of Soulのルーンを刻みます：\n\n$I1\nLesser Heal、Heal、Greater Heal、Flash Healが、回復した対象のWeakened Soulの残り時間を$D1短縮します。さらに、Power Word: Shieldの対象は、ダメージが吸収されてもダメージを受けたことで怒りを得るようになり、Righteous FuryはPower Word: Shieldで吸収されたダメージを治療であるかのように扱って発動します。", nil, 0x28fd638c, nil, "um" },
})
